package com.hospital.system.service; import com.hospital.system.model.Doctor; import com.hospital.system.repository.*; import com.hospital.system.exception.ApiException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*; @Service public class DoctorService {private final DoctorRepository r; private final DepartmentRepository d; public DoctorService(DoctorRepository r,DepartmentRepository d){this.r=r;this.d=d;} public List<Doctor> all(String q){return r.all(q);} public Doctor one(Long id){return r.one(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Doctor not found"));} private void check(Doctor x){if(!d.one(x.departmentId).isPresent())throw new ApiException(HttpStatus.BAD_REQUEST,"Department not found"); if(x.consultationFee==null||x.consultationFee.signum()<0)throw new ApiException(HttpStatus.BAD_REQUEST,"Consultation fee cannot be negative");} public Doctor add(Doctor x){check(x);r.add(x);return r.all(x.fullName).get(0);} public Doctor update(Long id,Doctor x){one(id);check(x);r.update(id,x);return one(id);} public void delete(Long id){one(id);r.delete(id);} }
